WITH valid AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, INITCAP(TRIM(firmware)) AS firmware_title FROM device_readings WHERE reading_ts > TIMESTAMP '2025-09-01 07:00:00' AND status_bits < 12) SELECT id, device_code, reading_ts, temp_c, humidity, pressure, firmware, firmware_title FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY reading_ts, id) AS latest_rank FROM valid) x WHERE latest_rank = 1
